('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Zuständigkeiten für Informationssicherheit sind im Anwendersupport verteilt. b) Nur die IT-Abteilung ist zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verteilt ja, IT allein falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Geschäftsleitung definiert Zuständigkeiten im Anwendersupport. b) Zuständigkeiten brauchen keine Dokumentation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leitung ja, Dokumentation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Datenschutzbeauftragter überwacht Zuständigkeiten im Anwendersupport. b) Zuständigkeiten betreffen nur technische Maßnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überwachung ja, auch organisatorisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Alle Mitarbeiter haben Zuständigkeiten für Sicherheitsvorfälle im Anwendersupport. b) Zuständigkeiten können nicht delegiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mitarbeiter ja, Delegation möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zuständigkeiten im Anwendersupport schließen Risikoüberwachung ein. b) Die Geschäftsleitung hat keine Zuständigkeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Risiko ja, Leitung beteiligt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

